var TTS_PREGENERATED = {
  "prompt_rewrite_done": "data:audio/mpeg;base64,",
  "prompt_rewrite_start": "data:audio/mpeg;base64,",
  "prompt_rewrite_success": "data:audio/mpeg;base64,",
  "voice_1": "data:audio/mpeg;base64,",
  "voice_10": "data:audio/mpeg;base64,",
  "voice_2": "data:audio/mpeg;base64,",
  "voice_3": "data:audio/mpeg;base64,",
  "voice_4": "data:audio/mpeg;base64,",
  "voice_5": "data:audio/mpeg;base64,",
  "voice_6": "data:audio/mpeg;base64,",
  "voice_7": "data:audio/mpeg;base64,",
  "voice_8": "data:audio/mpeg;base64,",
  "voice_9": "data:audio/mpeg;base64,",
};

function _getPregeneratedTts(voiceId){if(typeof TTS_PREGENERATED==='undefined')return null;return TTS_PREGENERATED['voice_'+voiceId]||null;}
function _getPregeneratedPrompt(promptKey){if(typeof TTS_PREGENERATED==='undefined')return null;return TTS_PREGENERATED['prompt_'+promptKey]||null;}
function _playPregeneratedTts(voiceId,volume,playbackRate){var d=_getPregeneratedTts(voiceId);if(!d)return null;try{var a=new Audio(d);a.volume=volume||1.0;a.playbackRate=playbackRate||1.0;a.play().catch(function(e){console.log('[TTS-PREGEN] Play failed:',e)});return a;}catch(e){return null;}}
function _playPregeneratedPrompt(promptKey){var d=_getPregeneratedPrompt(promptKey);if(!d)return null;try{var a=new Audio(d);a.volume=0.8;a.play().catch(function(e){console.log('[TTS-PREGEN] Prompt failed:',e)});return a;}catch(e){return null;}}
